.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:after,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:before,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:after,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:before,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn {
  box-sizing: border-box;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:after::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:before::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn::-moz-selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:after::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl *:before::selection,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn::selection {
  background: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn {
  outline: 0;
  display: block;
  width: 4em;
  height: 2em;
  position: relative;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn:after,
  .__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn:before {
  position: relative;
  display: block;
  content: "";
  width: 50%;
  height: 100%;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn:after {
  left: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl + .tgl-btn:before {
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl:checked + .tgl-btn:after {
  left: 50%;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl-flat + .tgl-btn {
  padding: 2px;
  transition: all 0.2s ease;
  background: #fff;
  border: 4px solid #f2f2f2;
  border-radius: 2em;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl-flat + .tgl-btn:after {
  transition: all 0.2s ease;
  background: #f2f2f2;
  content: "";
  border-radius: 1em;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl-flat:checked + .tgl-btn {
  border: 4px solid #7FC6A6;
}

.__UIV_SCOPE__ .checkbox-wrapper-9 .tgl-flat:checked + .tgl-btn:after {
  left: 50%;
  background: #7FC6A6;
}
